#include <compare>
#include <iostream>
#include <numeric>

class Fraction
{
public:
    Fraction(int num = 0, int den = 1) : m_num{ num }, m_den{ den }
    {
        // TODO: refuse a zero denominator (assert for now), then reduce
        reduce();
    }

    int num() const { return m_num; }
    int den() const { return m_den; }

    friend Fraction operator+(const Fraction& a, const Fraction& b)
    {
        return Fraction{ a.m_num * b.m_den + b.m_num * a.m_den, a.m_den * b.m_den };
    }

    // TODO: - * / , the compound versions, unary -, == and <=>

    friend std::ostream& operator<<(std::ostream& out, const Fraction& f)
    {
        return out << f.m_num << '/' << f.m_den;
    }

private:
    void reduce()
    {
        const int g{ std::gcd(m_num, m_den) };
        if (g != 0) { m_num /= g; m_den /= g; }
        if (m_den < 0) { m_num = -m_num; m_den = -m_den; }
    }

    int m_num{};
    int m_den{};
};

int main()
{
    Fraction a{ 1, 2 }, b{ 3, 4 };
    std::cout << a + b << '\n';
    return 0;
}
